#!/bin/bash
# 敬拜與禱告手冊 — Worship Book (psalms, hymns, prayer)
# Body is generated by books/bible/hymnWorship/build_book.py (CUV from ai-eden data,
# hymn texts from existing PubHub chapters). Template: templates/pdf/hymnworship.latex
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
OUTPUT_DIR="$PROJECT_ROOT/output"
BODY_MD="$OUTPUT_DIR/hymnworship-body.md"
COMBINED_MD="$OUTPUT_DIR/hymnworship-consolidated.md"
OUTPUT_PDF="$OUTPUT_DIR/hymnworship-consolidated.pdf"
TEMPLATE="$PROJECT_ROOT/templates/pdf/hymnworship.latex"
[ -f "$TEMPLATE" ] || { echo "ERROR: Template not found: $TEMPLATE"; exit 1; }
mkdir -p "$OUTPUT_DIR"
python3 -I "$PROJECT_ROOT/books/bible/hymnWorship/build_book.py" "$BODY_MD" || { echo "❌ body generation failed"; exit 1; }
cat > "$COMBINED_MD" <<'HEADER'
---
title: "敬拜與禱告手冊"
subtitle: "Worship Book — Psalms, Hymns and Prayer"
author: "PubHub 三書精讀系統"
date: "2026年11月"
publisher: "三書精讀出版系統"
copyright: |
  版權所有 © 2026 Soli Deo Gloria — 唯獨榮耀神

  **教會內部使用版（非賣品）。** 公開發行前須另行處理版權與授權。

  中文經文引自《聖經》和合本（公有領域）；英文經文為 NASB 1995（Scripture quotations from the New American Standard Bible®, Copyright © 1960, 1971, 1977, 1995 by The Lockman Foundation, lockman.org），取自 ai-eden.com，僅供教會內部使用；公開發行前須另行確認授權。所收聖詩皆為公有領域作品；中文歌詞凡標「編者試譯」者非通行譯本。現代詩歌僅列曲目，不印歌詞。

  本書的短禱與導語為編寫，非引用。逐項來源與未做的核對，見附錄三。
---

HEADER
# verse markers already emitted as \textsuperscript by the generator
cat "$BODY_MD" >> "$COMBINED_MD"
source "$SCRIPT_DIR/lib/latex-check.sh"
LATEX_LOG="${OUTPUT_PDF%.pdf}-build.log"
pandoc "$COMBINED_MD" -o "$OUTPUT_PDF" --verbose --pdf-engine=xelatex --template="$TEMPLATE" \
  --from=markdown-superscript-subscript --toc --toc-depth=1 --top-level-division=chapter > "$LATEX_LOG" 2>&1
latex_build_report "$?" "$LATEX_LOG" "$OUTPUT_PDF" || exit 1
